export function LegendElement({
  legendText = "{{legendText}}",
  position = "{{position}}",
  accent = "{{accent}}",
  bold = {{bold}},
}) {
  const style = position === "block"
    ? { display: "block", width: "100%", padding: "6px 0 10px", fontSize: 15, borderBottom: "1px solid #24143020", marginBottom: 6 }
    : { padding: "0 6px", fontSize: 13 };
  return (
    <fieldset style={{ width: 280, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143025", borderRadius: 10, padding: "8px 18px 16px" }}>
      <legend style={{ color: accent, fontWeight: bold ? 800 : 500, ...style }}>{legendText}</legend>
      <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 0", fontSize: 14 }}><input type="checkbox" style={{ accentColor: accent, width: 16, height: 16 }} defaultChecked /> Email</label>
      <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 0", fontSize: 14 }}><input type="checkbox" style={{ accentColor: accent, width: 16, height: 16 }} /> SMS</label>
    </fieldset>
  );
}
